const card=p=>`<article class="card"><a href="#produto-${p.id}">${cov(p)}</a><div class="ci"><h3>${esc(p.t)}</h3><p class="au">${esc(p.a||p.sub)}</p>${rate(p.id)}<p class="pr">${p.o?`<s>${R(p.o)}</s> `:''}<b>${R(p.p)}</b></p><div class="bt"><a class="b2" href="#produto-${p.id}">Ver produto</a><button class="b1" ${p.st<1?'disabled':''} onclick="add('${p.id}')">${p.st<1?'Esgotado':'Adicionar ao carrinho'}</button></div></div></article>`;
const sec=(t,sub,list,more)=>`<section class="s"><div class="w"><h2>${t}</h2><p>${sub}</p><div class="grid">${list.map(card).join('')||'<p>Em breve.</p>'}</div>${more?`<p style="margin-top:20px"><a class="b2" href="${more}">Ver todos</a></p>`:''}</div></section>`;
function add(id,q=1,quiet){const p=P.find(x=>x.id==id);if(!p)return;const n=Math.min((C[id]||0)+q,p.st);if(n<1)return;C[id]=n;sv();hdr();if(!quiet)toast(p.t+' foi adicionado ao carrinho')}
function toast(m){let t=$('#ts');if(!t){t=document.createElement('div');t.id='ts';t.setAttribute('role','status');t.style.cssText='position:fixed;bottom:calc(20px + env(safe-area-inset-bottom,0px));left:50%;transform:translateX(-50%);background:var(--ink);color:var(--bg);padding:10px 18px;border-radius:24px;z-index:30;font-size:14px;max-width:90vw';document.body.append(t)}t.textContent=m;t.style.display='block';clearTimeout(t.h);t.h=setTimeout(()=>t.style.display='none',2200)}
const qty=(id,d)=>{const p=P.find(x=>x.id==id),n=(C[id]||0)+d;if(n<1)delete C[id];else C[id]=Math.min(n,p.st);sv();hdr();route()};
const del=id=>{delete C[id];sv();hdr();route()};
function tot(){const it=Object.keys(C).map(i=>({p:P.find(x=>x.id==i),q:C[i]})).filter(x=>x.p),sub=it.reduce((s,x)=>s+x.p.p*x.q,0),cp=CP.find(c=>c.c==CU),ds=cp?sub*cp.v/100:0,fr=!it.length||sub-ds>=CF.free?0:+CF.ship;return{it,sub,ds,fr,t:sub-ds+fr,cp}}
function hdr(){$('#cc').textContent=Object.values(C).reduce((a,b)=>a+b,0);$('#logo').innerHTML=esc(CF.name)+'<small>Livraria &amp; Papelaria</small>';const h=location.hash.slice(1)||'home';document.querySelectorAll('#nv a').forEach(a=>a.classList.toggle('on',a.getAttribute('href')=='#'+h));
$('#ft').innerHTML=`<div><div class="lg">${esc(CF.name)}</div><p>Uma livraria pensada para quem ama ler: histórias que acolhem e pequenos detalhes de papelaria para a rotina.</p></div><div><h3>Navegue</h3><a href="#livros">Livros</a><a href="#papelaria">Papelaria</a><a href="#ofertas">Ofertas</a><a href="#sobre">Sobre nós</a></div><div><h3>Contato</h3><a target="_blank" rel="noopener" href="https://wa.me/${esc(CF.wa)}">WhatsApp</a><a target="_blank" rel="noopener" href="https://instagram.com/${esc(CF.insta)}">Instagram</a></div><div><h3>Informações</h3><a href="#privacidade">Política de privacidade</a><a href="#trocas">Trocas e devoluções</a><a href="#entrega">Informações de entrega</a></div>`}
const INFO={privacidade:['Política de privacidade','Usamos seus dados (nome, telefone e endereço) somente para atender e entregar seu pedido. Não vendemos nem compartilhamos suas informações com terceiros. Você pode pedir a exclusão dos seus dados pelo nosso WhatsApp.'],trocas:['Trocas e devoluções','Você pode solicitar troca ou devolução em até 7 dias após o recebimento, com o produto sem uso e na embalagem original. Fale conosco pelo WhatsApp informando o número do pedido.'],entrega:['Informações de entrega',`Entregamos em todo o Brasil. O frete é de ${R(CF.ship)} e é grátis em pedidos a partir de ${R(CF.free)}. O prazo é combinado no atendimento pelo WhatsApp.`],sobre:['Sobre nós','Nascemos do desejo de ter uma livraria aconchegante, daquelas em que dá vontade de ficar. Selecionamos livros que tocam, clássicos que permanecem e uma papelaria delicada para acompanhar cada leitura.']};
function home(){const rv=RV.filter(r=>r.s>=4).slice(-12).reverse();return`<div class="hero"><div class="w"><div><h1>Seu próximo capítulo começa aqui.</h1><p>Encontre histórias, inspirações e pequenos detalhes que tornam sua rotina mais especial.</p><a class="b1" href="#livros">Explorar livros</a></div>
<svg viewBox="0 0 400 300" role="img" aria-label="Pilha de livros e uma xícara de café"><ellipse cx="200" cy="268" rx="170" ry="14" fill="#8a6a52" opacity=".15"/><rect x="60" y="215" width="250" height="42" rx="5" fill="#8c3b3b"/><rect x="75" y="228" width="130" height="5" fill="#f6e6d0" opacity=".6"/><rect x="80" y="173" width="220" height="42" rx="5" fill="#2f4a3f"/><rect x="95" y="186" width="90" height="5" fill="#eadfc7" opacity=".6"/><rect x="70" y="131" width="235" height="42" rx="5" fill="#c9a34a"/><rect x="85" y="144" width="110" height="5" fill="#3b2a1c" opacity=".5"/><g transform="translate(250 60)"><path d="M0 40h90v50a40 40 0 0 1-40 40H40A40 40 0 0 1 0 90z" fill="#fffdf9" stroke="#b8926f" stroke-width="3"/><path d="M90 55h12a20 20 0 0 1 0 40H88" fill="none" stroke="#b8926f" stroke-width="5"/><ellipse cx="45" cy="42" rx="45" ry="8" fill="#6b4a35"/><path d="M30 30c-8-14 8-18 0-30M55 30c-8-14 8-18 0-30" fill="none" stroke="#b8926f" stroke-width="3" stroke-linecap="round" opacity=".6"/></g></svg></div></div>
${sec('Mais vendidos','Os queridinhos dos nossos leitores.',P.filter(p=>p.tg.includes('b')).slice(0,5),'#livros')}${sec('Livros em destaque','Seleção especial da casa.',P.filter(p=>p.k=='livro'&&p.tg.includes('f')).slice(0,5),'#livros')}${sec('Favoritos dos leitores','Histórias para reler e presentear.',P.filter(p=>p.tg.includes('v')).slice(0,5),'#livros')}${sec('Papelaria criativa','Detalhes que deixam a rotina mais bonita.',P.filter(p=>p.k=='papel').slice(0,5),'#papelaria')}${sec('Ofertas especiais','Preços especiais por tempo limitado.',P.filter(p=>p.o>0).slice(0,5),'#ofertas')}
<section class="s"><div class="w"><h2>O que dizem os leitores</h2><p>Avaliações enviadas pelos clientes. <button class="b2" style="padding:2px 14px;margin-left:8px" onclick="const m=this.closest('section').querySelector('.mt');m.classList.toggle('ps');this.textContent=m.classList.contains('ps')?'Retomar':'Pausar'">Pausar</button></p><div class="mq" role="group" aria-label="Avaliações dos clientes"><div class="mt" ${rv.length?'':'style="animation:none"'}>${rv.concat(rv).map((r,i)=>`<div class="rv" ${i>=rv.length?'aria-hidden="true"':''}><span class="rt">${stars(r.s)}</span><q>${esc(r.c)}</q><small>— ${esc(r.n)}${r.demo?' · exemplo demonstrativo':''}</small></div>`).join('')||'<p>As primeiras avaliações aparecerão aqui.</p>'}</div></div></div></section>
<div class="band" style="margin-top:56px"><section class="s"><div class="w"><h2>Receba novidades</h2><p>Lançamentos e promoções direto no seu e-mail.</p><form class="nl" onsubmit="event.preventDefault();L('nl',[]);S('nl',[...L('nl',[]),this.e.value]);this.innerHTML='<b>Obrigado! Você está na lista.</b>'"><input name="e" type="email" required placeholder="seu@email.com" aria-label="E-mail"><button class="b1">Assinar</button></form></div></section></div>`}
function cat(kind,title,extra){const subs=[...new Set(P.filter(p=>kind=='all'||p.k==kind).map(p=>p.sub))],aus=[...new Set(P.filter(p=>p.a).map(p=>p.a))].sort();
return`<div class="pg"><div class="w"><h1>${title}</h1><div class="flt"><div><label for="fs">Categoria</label><select id="fs" onchange="F.sub=this.value;gr('${kind}','${extra||''}')"><option value="">Todas</option>${subs.map(s=>`<option ${F.sub==s?'selected':''}>${esc(s)}</option>`).join('')}</select></div>${kind!='papel'?`<div><label for="fa">Autor</label><select id="fa" onchange="F.au=this.value;gr('${kind}','${extra||''}')"><option value="">Todos</option>${aus.map(s=>`<option ${F.au==s?'selected':''}>${esc(s)}</option>`).join('')}</select></div>`:''}<div><label for="fm">Preço até (R$)</label><input id="fm" type="number" min="0" value="${F.max}" oninput="F.max=this.value;gr('${kind}','${extra||''}')"></div><div><label for="fo">Ordenar por</label><select id="fo" onchange="F.sort=this.value;gr('${kind}','${extra||''}')">${[['rel','Relevância'],['menor','Menor preço'],['maior','Maior preço'],['vend','Mais vendidos'],['aval','Melhor avaliados'],['lanc','Lançamentos']].map(o=>`<option value="${o[0]}" ${F.sort==o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></div></div><div class="grid" id="gd"></div></div></div>`}
function gr(kind,extra){const q=F.q.toLowerCase();let l=P.filter(p=>(kind=='all'||p.k==kind)&&(extra!='o'||p.o>0)&&(!F.sub||p.sub==F.sub)&&(!F.au||p.a==F.au)&&(!F.max||p.p<=+F.max)&&(!q||(p.t+' '+p.a+' '+p.sub).toLowerCase().includes(q)));const s=F.sort,w=p=>p.tg.includes(s=='vend'?'b':'n')?0:1;
if(s=='menor')l.sort((a,b)=>a.p-b.p);if(s=='maior')l.sort((a,b)=>b.p-a.p);if(s=='aval')l.sort((a,b)=>stt(b.id).a-stt(a.id).a);if(s=='vend'||s=='lanc')l.sort((a,b)=>w(a)-w(b));$('#gd').innerHTML=l.map(card).join('')||'<p>Nenhum produto encontrado. Tente outros filtros.</p>'}
function prod(id){const p=P.find(x=>x.id==id);if(!p)return'<div class="pg"><div class="w"><h1>Produto não encontrado</h1><a class="b1" href="#livros">Voltar</a></div></div>';const s=stt(id),r=RV.filter(x=>x.pid==id).reverse();
return`<div class="pg"><div class="w"><div class="pd"><div><div class="big" data-v="0" id="bg">${cov(p,1)}</div><div class="th"><button class="b2" onclick="$('#bg').dataset.v=0">Frente</button><button class="b2" onclick="$('#bg').dataset.v=1">Lombada</button><button class="b2" onclick="$('#bg').dataset.v=2">Detalhe</button></div></div>
<div><span class="tag">${esc(p.sub)}</span><h1 style="font-size:42px;margin:8px 0">${esc(p.t)}</h1>${p.a?`<p class="au" style="font-size:17px">${esc(p.a)}</p>`:''}<p>${rate(id)} ${s.n?s.a.toFixed(1)+' de 5':''}</p><p class="pr" style="font-size:30px">${p.o?`<s>${R(p.o)}</s> `:''}<b>${R(p.p)}</b></p><p>${esc(p.d)}</p><p><b style="color:${p.st>0?'var(--gr)':'#a33'}">${p.st>0?(p.st<=5?'Últimas '+p.st+' unidades':'Disponível em estoque'):'Indisponível no momento'}</b></p>
<p><span class="q"><button aria-label="Diminuir" onclick="let i=$('#qt');i.value=Math.max(1,i.value-1)">−</button><input id="qt" type="number" value="1" min="1" max="${p.st}" style="width:54px;border:0;text-align:center;padding:4px;background:none"><button aria-label="Aumentar" onclick="let i=$('#qt');i.value=Math.min(${p.st},+i.value+1)">+</button></span></p>
<div style="display:flex;gap:10px;flex-wrap:wrap"><button class="b2" ${p.st<1?'disabled':''} onclick="add('${id}',+$('#qt').value)">Adicionar ao carrinho</button><button class="b1" ${p.st<1?'disabled':''} onclick="add('${id}',+$('#qt').value,1);go('carrinho')">Comprar agora</button></div></div></div>
<section class="s"><h2>Avaliações dos clientes</h2><div class="grid" style="margin:16px 0">${r.map(x=>`<div class="rv"><span class="rt">${stars(x.s)}</span><q>${esc(x.c)}</q><small>— ${esc(x.n)} · ${new Date(x.d+'T12:00').toLocaleDateString('pt-BR')}${x.demo?' · exemplo demonstrativo':''}</small></div>`).join('')||'<p>Ainda não há avaliações. Seja a primeira pessoa a avaliar!</p>'}</div>
<form class="box fm" style="max-width:600px" onsubmit="event.preventDefault();rvAdd('${id}',this)"><h3 class="f">Avaliar este produto</h3><div><label>Seu nome<input name="n" required maxlength="40"></label></div><div><label>Nota<select name="s"><option>5</option><option>4</option><option>3</option><option>2</option><option>1</option></select></label></div><div class="f"><label>Comentário<textarea name="c" required rows="3" maxlength="500"></textarea></label></div><button class="b1 f">Enviar avaliação</button></form></section></div></div>`}
function rvAdd(pid,f){RV.push({id:'r'+Date.now(),pid,n:f.n.value.trim(),s:+f.s.value,d:new Date().toISOString().slice(0,10),c:f.c.value.trim()});sv();toast('Obrigado pela sua avaliação!');route()}
function cart(){const t=tot();if(!t.it.length)return'<div class="pg"><div class="w"><h1>Seu carrinho</h1><p>Seu carrinho está vazio.</p><a class="b1" href="#livros">Explorar livros</a></div></div>';
return`<div class="pg"><div class="w"><h1>Seu carrinho</h1><div class="two"><div>${t.it.map(x=>`<div class="row"><a href="#produto-${x.p.id}" style="width:70px">${cov(x.p)}</a><div><b>${esc(x.p.t)}</b><br><small>${R(x.p.p)} cada</small><br><span class="q"><button aria-label="Diminuir" onclick="qty('${x.p.id}',-1)">−</button>${x.q}<button aria-label="Aumentar" onclick="qty('${x.p.id}',1)">+</button></span></div><div style="text-align:right"><b>${R(x.p.p*x.q)}</b><br><button class="b2" style="margin-top:6px" onclick="del('${x.p.id}')">Remover</button></div></div>`).join('')}</div>
<div class="box"><h3>Resumo</h3><p><span>Subtotal</span><span>${R(t.sub)}</span></p>${t.ds?`<p><span>Cupom ${esc(CU)}</span><span>− ${R(t.ds)}</span></p>`:''}<p><span>Frete</span><span>${t.fr?R(t.fr):'Grátis'}</span></p><p style="font-size:20px"><b>Total</b><b>${R(t.t)}</b></p><form style="display:flex;gap:6px;margin:12px 0" onsubmit="event.preventDefault();cup(this.c.value)"><input name="c" placeholder="Cupom de desconto" aria-label="Cupom"><button class="b2">Aplicar</button></form><a class="b1" style="display:block" href="#checkout">Finalizar compra</a></div></div></div></div>`}
function cup(c){c=c.trim().toUpperCase();if(!c){CU='';}else if(CP.find(x=>x.c==c))CU=c;else{toast('Cupom inválido');return}sv();route()}
function chk(){const t=tot();if(!t.it.length)return cart();const c=L('cli',{}),f=(k,l,x='')=>`<div class="${x}"><label>${l}<input name="${k}" value="${esc(c[k]||'')}" required></label></div>`;
return`<div class="pg"><div class="w"><h1>Finalizar pedido</h1><div class="two"><form id="ck" class="fm box" onsubmit="event.preventDefault();wa(this)">${f('nome','Nome completo','f')}${f('tel','Telefone (com DDD)')}${f('cep','CEP')}${f('end','Endereço','f')}${f('num','Número')}<div><label>Complemento<input name="comp" value="${esc(c.comp||'')}"></label></div>${f('bai','Bairro')}${f('cid','Cidade')}${f('uf','Estado (UF)')}<div class="f"><label>Forma de pagamento desejada<select name="pay"><option>Pix</option><option>Cartão de crédito</option><option>Cartão de débito</option><option>Boleto</option></select></label></div><div class="f"><button class="b3">FINALIZAR PEDIDO PELO WHATSAPP</button></div><p class="f" style="font-size:13px;margin:0">Seu pedido só é confirmado após o atendimento da loja pelo WhatsApp.</p></form>
<div class="box"><h3>Resumo</h3>${t.it.map(x=>`<p><span>${x.q}× ${esc(x.p.t)}</span><span>${R(x.p.p*x.q)}</span></p>`).join('')}<p><span>Subtotal</span><span>${R(t.sub)}</span></p>${t.ds?`<p><span>Cupom</span><span>− ${R(t.ds)}</span></p>`:''}<p><span>Frete</span><span>${t.fr?R(t.fr):'Grátis'}</span></p><p style="font-size:20px"><b>Total</b><b>${R(t.t)}</b></p></div></div></div></div>`}
function wa(f){const d=Object.fromEntries(new FormData(f)),t=tot();S('cli',d);
const m=`Olá! Gostaria de finalizar meu pedido na livraria.\n\nINFORMAÇÕES DO CLIENTE:\nNome: ${d.nome}\nTelefone: ${d.tel}\n\nENDEREÇO DE ENTREGA:\n${d.end}, ${d.num}${d.comp?' - '+d.comp:''}\n${d.bai} - ${d.cid}/${d.uf.toUpperCase()}\nCEP: ${d.cep}\n\nPRODUTOS:\n${t.it.map(x=>`${x.p.t}\nQuantidade: ${x.q}\nPreço individual: ${R(x.p.p)}`).join('\n\n')}\n\nSubtotal: ${R(t.sub)}\n${t.ds?`Desconto (${CU}): -${R(t.ds)}\n`:''}Frete: ${t.fr?R(t.fr):'Grátis'}\nTOTAL: ${R(t.t)}\n\nForma de pagamento: ${d.pay}\n\nAguardo a confirmação do meu pedido. Obrigado!`;
const u=`https://wa.me/${CF.wa}?text=${encodeURIComponent(m)}`;OR.push({id:'P'+Date.now().toString().slice(-6),d:new Date().toLocaleString('pt-BR'),cli:d.nome,tel:d.tel,tot:t.t,items:t.it.map(x=>x.q+'× '+x.p.t).join('; '),st:'Aguardando atendimento',ph:d.tel});C={};CU='';sv();hdr();
$('#app').innerHTML=`<div class="pg"><div class="w"><h1>Pedido enviado ao WhatsApp</h1><div class="ok"><p>Seu pedido foi preparado e será enviado à loja pelo WhatsApp. <b>Ele ainda não está confirmado</b>: a confirmação acontece após o atendimento da loja.</p>${CF.def?'<p><b>Atenção (lojista):</b> o número de WhatsApp da loja ainda é o padrão. Altere em Área do lojista → Loja.</p>':''}<a class="b3" style="display:block" target="_blank" rel="noopener" href="${u}">Abrir WhatsApp</a></div></div></div>`;window.open(u,'_blank','noopener')}
function conta(){const c=L('cli',{}),o=OR.filter(x=>c.tel&&x.ph==c.tel);return`<div class="pg"><div class="w"><h1>Minha conta</h1><p>${c.nome?'Olá, '+esc(c.nome)+'! ':''}Pedidos feitos neste dispositivo:</p>${o.length?`<table><tr><th>Pedido</th><th>Data</th><th>Total</th><th>Status</th></tr>${o.map(x=>`<tr><td>${x.id}</td><td>${x.d}</td><td>${R(x.tot)}</td><td>${esc(x.st)}</td></tr>`).join('')}</table>`:'<p>Você ainda não fez pedidos.</p>'}</div></div>`}
function admin(){if(!AU)return`<div class="pg"><div class="w"><h1>Área do lojista</h1><form class="box" style="max-width:360px" onsubmit="event.preventDefault();if(this.p.value==CF.pin){AU=1;route()}else toast('PIN incorreto')"><label>PIN de acesso<input name="p" type="password" required></label><button class="b1" style="margin-top:12px">Entrar</button></form></div></div>`;
const I=(n,l,v='',t='text')=>`<div><label>${l}<input name="${n}" type="${t}" value="${esc(v)}" ${t=='number'?'step="0.01" min="0"':''}></label></div>`;let b='';
if(AT=='Produtos')b=`<form id="pf" class="fm box" onsubmit="event.preventDefault();psave(this)"><h3 class="f">Cadastrar / editar produto</h3><input type="hidden" name="id">${I('t','Nome')}${I('a','Autor (livros)')}<div><label>Tipo<select name="k"><option value="livro">Livro</option><option value="papel">Papelaria</option></select></label></div>${I('sub','Categoria (ex.: Livros, Post-its)')}${I('p','Preço (R$)','','number')}${I('o','Preço antigo (oferta)','','number')}${I('st','Estoque','','number')}${I('tg','Marcas: b=mais vendido f=destaque v=favorito n=lançamento')}<div class="f"><label>Descrição<textarea name="d" rows="2"></textarea></label></div><div class="f"><label>Imagem da capa/foto<input name="img" type="file" accept="image/*"></label></div><button class="b1 f">Salvar produto</button></form><table style="margin-top:18px"><tr><th>Produto</th><th>Preço</th><th>Estoque</th><th></th></tr>${P.map(p=>`<tr><td>${esc(p.t)}</td><td>${R(p.p)}</td><td>${p.st}</td><td><button class="b2" onclick="pedit('${p.id}')">Editar</button> <button class="b2" onclick="if(confirm('Excluir?')){P=P.filter(x=>x.id!='${p.id}');sv();route()}">Excluir</button></td></tr>`).join('')}</table>`;
if(AT=='Pedidos')b=OR.length?`<table><tr><th>Pedido</th><th>Cliente</th><th>Itens</th><th>Total</th><th>Status</th></tr>${OR.map((x,i)=>`<tr><td>${x.id}<br><small>${x.d}</small></td><td>${esc(x.cli)}<br><small>${esc(x.tel)}</small></td><td>${esc(x.items)}</td><td>${R(x.tot)}</td><td><select onchange="OR[${i}].st=this.value;sv()">${['Aguardando atendimento','Confirmado','Enviado','Entregue','Cancelado'].map(s=>`<option ${s==x.st?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')}</table>`:'<p>Nenhum pedido ainda.</p>';
if(AT=='Avaliações')b=RV.length?`<p><button class="b2" onclick="if(confirm('Remover todas as avaliações de exemplo?')){RV=RV.filter(x=>!x.demo);sv();route()}">Remover todos os exemplos</button></p><table>${RV.map((x,i)=>`<tr><td>${esc(P.find(p=>p.id==x.pid)?.t||x.pid)}</td><td>${stars(x.s)} ${esc(x.n)}<br>${esc(x.c)}${x.demo?' <i>(demonstrativo)</i>':''}</td><td><button class="b2" onclick="RV.splice(${i},1);sv();route()">Excluir</button></td></tr>`).join('')}</table>`:'<p>Sem avaliações.</p>';
if(AT=='Cupons')b=`<form class="fm box" onsubmit="event.preventDefault();CP.push({c:this.c.value.toUpperCase(),v:+this.v.value});sv();route()">${I('c','Código')}${I('v','Desconto (%)','','number')}<button class="b1 f">Criar cupom</button></form><table style="margin-top:14px">${CP.map((c,i)=>`<tr><td>${esc(c.c)}</td><td>${c.v}%</td><td><button class="b2" onclick="CP.splice(${i},1);sv();route()">Excluir</button></td></tr>`).join('')}</table>`;
if(AT=='Loja')b=`<form class="fm box" onsubmit="event.preventDefault();CF={...CF,name:this.name.value,wa:this.wa.value.replace(/\\D/g,''),def:0,ship:+this.ship.value,free:+this.free.value,insta:this.insta.value,pin:this.pin.value};sv();toast('Configurações salvas');route()">${I('name','Nome da loja',CF.name)}${I('wa','WhatsApp com DDI+DDD (ex.: 5511999998888)',CF.wa)}${I('ship','Frete padrão (R$)',CF.ship,'number')}${I('free','Frete grátis a partir de (R$)',CF.free,'number')}${I('insta','Instagram (usuário)',CF.insta)}${I('pin','PIN do painel',CF.pin)}<button class="b1 f">Salvar</button></form>`;
return`<div class="pg"><div class="w"><h1>Painel da loja</h1><div class="tb">${['Produtos','Pedidos','Avaliações','Cupons','Loja'].map(t=>`<button class="b2 ${t==AT?'on':''}" onclick="AT='${t}';route()">${t}</button>`).join('')}<button class="b2" onclick="AU=0;route()">Sair</button></div>${b}</div></div>`}
function pedit(id){const p=P.find(x=>x.id==id),f=$('#pf');['id','t','a','k','sub','p','o','st','tg','d'].forEach(k=>f[k].value=p[k]??'');f.scrollIntoView()}
function psave(f){const go2=img=>{const o={id:f.id.value||'x'+Date.now(),k:f.k.value,sub:f.sub.value||(f.k.value=='livro'?'Livros':'Papelaria'),t:f.t.value,a:f.a.value,p:+f.p.value,o:+f.o.value||0,st:+f.st.value||0,tg:f.tg.value,d:f.d.value,bg:'#d9c3a5',fg:'#4a3426'},i=P.findIndex(x=>x.id==o.id);if(i>=0)P[i]={...P[i],...o,...(img?{img}:{})};else P.push({...o,...(img?{img}:{})});sv();toast('Produto salvo');route()};
const fl=f.img.files[0];if(!fl)return go2();const r=new FileReader();r.onload=()=>{const m=new Image();m.onload=()=>{const k=Math.min(1,500/m.width),c=document.createElement('canvas');c.width=m.width*k;c.height=m.height*k;c.getContext('2d').drawImage(m,0,0,c.width,c.height);go2(c.toDataURL('image/jpeg',.8))};m.src=r.result};r.readAsDataURL(fl)}
function route(){const h=location.hash.slice(1)||'home',a=$('#app');hdr();let v;
if(h=='home')v=home();else if(h=='livros'){v=cat('livro','Livros');}else if(h=='papelaria'){v=cat('papel','Papelaria')+kits()}else if(h=='ofertas')v=cat('all','Ofertas especiais');else if(h=='busca')v=cat('all','Resultados da busca');else if(h.startsWith('produto-'))v=prod(h.slice(8));else if(h=='carrinho')v=cart();else if(h=='checkout')v=chk();else if(h=='conta')v=conta();else if(h=='admin')v=admin();else if(INFO[h])v=`<div class="pg"><div class="w"><h1>${INFO[h][0]}</h1><p style="max-width:680px;font-size:18px">${INFO[h][1]}</p></div></div>`;else v=home();
a.innerHTML=v;if($('#gd'))gr(h=='livros'?'livro':h=='papelaria'?'papel':'all',h=='ofertas'?'o':'');if(!route.k)window.scrollTo(0,0)}
const kits=()=>`<section class="s" style="padding-top:0"><div class="w"><h2>Kits para presentear</h2><p>Combinações prontas, embaladas com carinho.</p><div class="grid">${P.filter(p=>p.sub=='Kits de papelaria').map(card).join('')}</div></div></section>`;
['F'].forEach(()=>0);addEventListener('hashchange',()=>{if(!/^#(livros|papelaria|ofertas)$/.test(location.hash))F={q:F.q,sub:'',au:'',max:'',sort:'rel'};if(location.hash=='#livros'||location.hash=='#papelaria'||location.hash=='#ofertas')F={q:'',sub:'',au:'',max:'',sort:'rel'};route()});route();
let mqx=0,mqT=0,mqH=0;
addEventListener('mouseover',e=>{mqH=e.target.closest&&e.target.closest('.mq')?1:0});
document.documentElement.addEventListener('mouseleave',()=>{mqH=0});
addEventListener('touchstart',e=>{if(e.target.closest&&e.target.closest('.mq'))mqH=1},{passive:true});
addEventListener('touchend',()=>setTimeout(()=>{mqH=0},1500),{passive:true});
(function tick(ts){const t=document.querySelector('.mt');if(t&&t.children.length>1&&!mqH&&!t.classList.contains('ps')){const half=t.scrollWidth/2,v=matchMedia('(prefers-reduced-motion:reduce)').matches?.02:.045;mqx-=Math.min(ts-mqT,64)*v;if(-mqx>=half)mqx+=half;t.style.transform='translateX('+mqx+'px)'}mqT=ts;requestAnimationFrame(tick)})(0);
